head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vAxisType = "";
scwin.vHorizLimitCnt = 0;
window.onunload = function() {
    opener.fn_getBeforeRadioBtn("ALL");
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P4.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.vAxisType = opener.scwin.vAxisType;
    scwin.vHorizLimitCnt = opener.scwin.vHorizLimitCnt;
    scwin.initDs();

    // 조회
    await scwin.search();

    // 이전에 선택된 항목을 화면에 display
    scwin.displayBefItem();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Year_OnLoadError
 * @description dts_Year 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Year_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Year);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P4.dts_Year_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Year_OnLoadCompleted
 * @description dts_Year 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Year_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Year.errorMsg) {
            await $c.win.alert(dts_Year.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P4.dts_Year_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        // opener.fn_getBeforeRadioBtn("ALL");
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P4.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Confirm_onclick = async function() {
    try {
        // 확인버튼 클릭
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P4.img_Confirm_onclick" });
    }
};

/**
 * @method
 * @name image_1_onclick
 * @description image_1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.image_1_onclick = async function() {
    try {
        await scwin.selected();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P4.image_1_onclick" });
    }
};

/**
 * @method
 * @name image_2_onclick
 * @description image_2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.image_2_onclick = function() {
    try {
        scwin.rmSelected();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600_P4.image_2_onclick" });
    }
};

/**
 * @method
 * @name image_3_onclick
 * @description 「전체선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.image_3_onclick = function() {
    try {
        scwin.selectAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600_P4.image_3_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.clearDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_Year",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name displayBefItem
 * @description 이미 선택되어있는 항목을 화면이 open할때 화면에 display한다.
 * @returns {void}
 * @hidden N
 */
scwin.displayBefItem = function() {
    const tmpDs = opener.dts_Fz531;
    dts_SelectYear.setBroadcast(false);
    for (let nRow = 1; nRow <= tmpDs.getRowCount(); nRow++) {
        // AXIS_TYP 2 가로, 3 세로 / ITEM_TYP  0 년도, 1 계정, 3 회사
        if ((tmpDs.getCellData(nRow, "AXIS_TYP") === "2" || tmpDs.getCellData(nRow, "AXIS_TYP") === "3") && tmpDs.getCellData(nRow, "ITEM_TYP") === "0") {
            dts_SelectYear.insertRow();
            const nIdx = dts_SelectYear.getRowPosition();
            dts_SelectYear.setCellData(nIdx, "LV", "2");
            dts_SelectYear.setCellData(nIdx, "YYYY", tmpDs.getCellData(nRow, "ITEM_CD"));
        }
    }
    dts_SelectYear.setBroadcast(true, true); // end for

};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {

    // dts_SelectYear.setDataHeader();
    // dts_SelectAcnt.AddRow();
    // var nRow = dts_SelectAcnt.RowPosition;
    // dts_SelectAcnt.NameString(nRow, "LV") = "1";
    // dts_SelectAcnt.NameString(nRow, "ACCNT_NM") = "선택된 계정";     // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};

/**
 * @method
 * @name clearDs
 * @description 데이터셋 clear.
 * @returns {void}
 * @hidden N
 */
scwin.clearDs = function() {
    dts_Year.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    if (dts_SelectYear.getRowCount() < 1) {
        return;
    }
    const arrPar = new Array();
    for (let nRow = 1; nRow <= dts_SelectYear.getRowCount(); nRow++) {
        const sItemCd = dts_SelectYear.getCellData(nRow, "YYYY");
        const sItemNM = dts_SelectYear.getCellData(nRow, "YYYY");
        const sItemTyp = "0"; // 0:년도, 1:계정, 3:회사
        const sAxisTyp = scwin.vAxisType; // AXIS_TYP  1:기준, 2: 가로, 3:세로
        const sColYear = "0000"; // COL_YEAR

        if (sItemCd !== "") {
            arrPar[nRow - 1] = {
                ITEM_CD: sItemCd,
                ITEM_NM: sItemNM,
                ITEM_TYP: sItemTyp,
                AXIS_TYP: sAxisTyp,
                COL_YEAR: sColYear
            };
        }
    }
    $c.frame.path("../").fn_SetAxisInfo(arrPar);
    await $c.win.closePopup();
};

/**
 * @method
 * @name rmSelected
 * @description 선택제거
 * @returns {void}
 * @hidden N
 */
scwin.rmSelected = function() {
    trv_SelectedYear.ReDraw = false;
    dts_SelectYear.setBroadcast(false);
    for (let nRow = dts_SelectYear.getRowCount(); nRow >= 1; nRow--) {
        if (trv_SelectedYear.findNodeByIndex(nRow, false).checked) {
            dts_SelectYear.removeRow(nRow);
        }
    }
    dts_SelectYear.setBroadcast(true, true);
    trv_SelectedYear.ReDraw = true;
};

/**
 * @method
 * @name selected
 * @description 선택
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function() {
    // dts_SelectYear.ClearData();

    // 가로 세팅이면 갯수 체크 :  2 가로, 3 세로
    if (scwin.vAxisType === "2") {
        // 선택된것 갯수
        let nSelectCnt = dts_SelectYear.getRowCount();
        for (let nRow = 1; nRow <= dts_Year.getRowCount(); nRow++) {
            if (trv_Year.findNodeByIndex(nRow, false).checked) {
                nSelectCnt++;
            }
        }
        // 갯수체크
        if (nSelectCnt > scwin.vHorizLimitCnt) {
            await $c.win.alert("선택된 가로항목이 10개를 초과합니다.");
            return;
        }
    }
    dts_SelectYear.setBroadcast(false);
    for (let nRow = 1; nRow <= dts_Year.getRowCount(); nRow++) {
        if (trv_Year.findNodeByIndex(nRow, false).checked) {
            // 중복 체크.
            const nTmpIdx1 = $c.cp.getNameValueRow(dts_SelectYear, "YYYY", dts_Year.getCellData(nRow, "YYYY"));
            if (nTmpIdx1 >= 1) {
                trv_Year.checkByIndex(nRow, false); // 체크박스 언체크
                continue;
            }
            dts_SelectYear.insertRow();
            dts_SelectYear.setCellData(dts_SelectYear.getRowPosition(), "LV", dts_Year.getCellData(nRow, "LV"));
            dts_SelectYear.setCellData(dts_SelectYear.getRowPosition(), "YYYY", dts_Year.getCellData(nRow, "YYYY"));
            trv_Year.checkByIndex(nRow, false); // 체크박스 언체크

        }
    }
    dts_SelectYear.setBroadcast(true, true);
};

/**
 * @method
 * @name selectAll
 * @description 전체선택
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    for (let nRow = 1; nRow <= dts_Year.getRowCount(); nRow++) {
        trv_Year.checkByIndex(nRow, true);
    }
};
